SELECT

FROM CHB_BRANCH_NETWORK


		AND BRANCH_NO LIKE concat_ws('','%',#{branchNo},'%')


		AND BRANCH_NAME LIKE concat_ws('','%',#{branchName},'%')


		AND BRANCH_FSA = #{branchFsa}


		AND NETWORK_NO = #{networkNo}


		AND STATUS = #{status}


ORDER BY BRANCH_NO

