mapper.insert:
insert into CHB_BRANCH_NETWORK (BRANCH_NO,BRANCH_NAME, BRANCH_FSA,NETWORK_NO,REMARK,CREATE_USER, CREATE_TIME,UPDATE_USER,UPDATE_TIME) select A.* from (
select #{item.branchNo,jdbcType=VARCHAR} BRANCH_NO, #{item.branchName,jdbcType=VARCHAR} BRANCH_NAME, #{item.branchFsa,jdbcType=VARCHAR} BRANCH_FSA, #{item.networkNo,jdbcType=VARCHAR} NETWORK_NO, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME from dual
) A ON DUPLICATE KEY UPDATE BRANCH_NAME=A.BRANCH_NAME, BRANCH_FSA=A.BRANCH_FSA, NETWORK_NO=A.NETWORK_NO, REMARK=A.REMARK, UPDATE_USER=A.UPDATE_USER, UPDATE_TIME=NOW()

